<?php
if(PHP_SAPI!=='cli')exit(1);putenv('TIVOLI_TEST_MODE=1');require dirname(__DIR__,2).'/bootstrap/security.php';
use Tivoli\Service\HandoverService;use Tivoli\Service\FinanceService;
$a=access_service();$r=$a->repo;if((int)$r->run('SELECT @@port')->fetchColumn()!==3307||$r->run('SELECT DATABASE()')->fetchColumn()!=='tivoli_auth_test'||$r->run('SELECT marker FROM security_test_marker')->fetchColumn()!=='synthetic-auth-only-v1')exit(2);
$clock='2045-04-04 20:00:00';$h=new HandoverService($a,$clock);$f=new FinanceService($a,$clock);$count=0;
function rk():string{return bin2hex(random_bytes(16));}
function ra():int{global $r;$r->run("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'clerk')",['Synthetic custody race',rk().'@example.invalid',password_hash('Synthetic race only',PASSWORD_BCRYPT)]);$id=(int)$r->db->lastInsertId();$r->run('INSERT INTO security_accounts(user_id,must_change_password) VALUES(?,0)',[$id]);$r->run("INSERT INTO security_user_roles SELECT ?,id FROM security_roles WHERE name='clerk'",[$id]);return $id;}
function seed():array{global $f;$sender=ra();$one=ra();$two=ra();$f->execute($sender,'income_record',['payer'=>'Synthetic race','activity'=>'Synthetic courtyard','amount'=>'100.00','method'=>'cash','treatment'=>'earned','provided'=>'1'],rk());return [$sender,$one,$two];}
function jobs(array $jobs):array{
 $barrier=dirname(__DIR__,2).'/.local-setup/handover-race-'.rk();$all=[];
 foreach($jobs as $i=>$job){$p=proc_open([PHP_BINARY,__DIR__.'/handover_worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($job+['barrier'=>$barrier,'worker'=>$i]));fclose($pipes[0]);$all[]=[$p,$pipes];}
 $limit=microtime(true)+15;while(!is_file($barrier.'.ready0')||!is_file($barrier.'.ready1')){if(microtime(true)>$limit)throw new RuntimeException('Barrier timeout');usleep(10000);}
 file_put_contents($barrier.'.go','go');$out=[];foreach($all as [$p,$pipes]){$result=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err)throw new RuntimeException('Worker failed');$out[]=json_decode($result,true,512,JSON_THROW_ON_ERROR);}foreach(['.ready0','.ready1','.go'] as $suffix)unlink($barrier.$suffix);return $out;
}
function job(int $actor,string $action,array $input,string $service='handover',?string $key=null):array{global $clock;return ['actor'=>$actor,'action'=>$action,'input'=>$input,'service'=>$service,'key'=>$key??rk(),'clock'=>$clock];}
function pass(bool $ok,string $label):void{global $count;if(!$ok)throw new RuntimeException($label);$count++;echo "PASS $label\n";}
[$sender,$one,$two]=seed();$send=['amount'=>'70.00','passed'=>'1'];$out=jobs([job($sender,'cash_send',$send+['recipient_id'=>(string)$one]),job($sender,'cash_send',$send+['recipient_id'=>(string)$two])]);pass(count(array_filter($out,fn($x)=>$x['ok']))===1&&$f->cash()['custodians'][$sender]['reserved']===7000,'Competing transfers cannot overspend one source');
[$sender,$one,$two]=seed();$out=jobs([job($sender,'cash_send',['amount'=>'100.00','recipient_id'=>(string)$one,'passed'=>'1']),job($sender,'deposit_record',['amount'=>'100.00','fee'=>'0','date'=>'2045-04-04','reference'=>rk()],'finance')]);pass(count(array_filter($out,fn($x)=>$x['ok']))===1,'Deposit versus transfer preserves one reservation');
[$sender,$one,$two]=seed();$id=$h->execute($sender,'cash_send',['amount'=>'100.00','recipient_id'=>(string)$one,'passed'=>'1'],rk())['id'];$ack=['id'=>(string)$id,'version'=>$h->detail($one,$id)['version'],'received'=>'1'];$key=rk();$j=job($one,'cash_ack',$ack,'handover',$key);$out=jobs([$j,$j]);pass(count(array_filter($out,fn($x)=>$x['ok']))===2&&$f->cash()['custodians'][$one]['held']===10000&&(int)$r->run("SELECT COUNT(*) FROM finance_events WHERE kind='cash_transfer_acknowledged' AND target_id=?",[(string)$id])->fetchColumn()===1,'Concurrent acknowledgement retries move custody once');
[$sender,$one,$two]=seed();$id=$h->execute($sender,'cash_send',['amount'=>'100.00','recipient_id'=>(string)$one,'passed'=>'1'],rk())['id'];$ack=['id'=>(string)$id,'version'=>$h->detail($one,$id)['version'],'received'=>'1'];$out=jobs([job($one,'cash_ack',$ack),job($one,'deposit_record',['amount'=>'100.00','fee'=>'0','date'=>'2045-04-04','reference'=>rk()],'finance')]);$held=$f->cash()['custodians'][$one]['held'];pass($out[0]['ok']&&$held===($out[1]['ok']?0:10000),'Acknowledgement versus receiver deposit retains exact cash');
echo "TOTAL $count handover concurrency scenarios passed.\n";
